(() => {
  const status = document.querySelector("#keeper-status");
  const lanternButton = document.querySelector("#keeper-lantern");
  const rationButton = document.querySelector("#keeper-ration");
  const lanternCount = document.querySelector("#keeper-lantern-count");
  const rationCount = document.querySelector("#keeper-ration-count");
  const clueList = document.querySelector("#keeper-clue-list");
  const fullscreenButton = document.querySelector("#keeper-fullscreen");
  const terminalButton = document.querySelector("#keeper-terminal");
  const endButton = document.querySelector("#keeper-end");
  const exitButton = document.querySelector("#keeper-exit");
  let submittingAction = false;
  let fullscreenBusy = false;
  let fullscreenActive = false;
  let previousValues = null;
  const setStatus = (text, busy, error = false) => {
    if (!status) return;
    status.textContent = text;
    status.dataset.busy = busy ? "true" : "false";
    status.dataset.error = error ? "true" : "false";
  };
  const pulse = element => {
    if (!element) return;
    element.classList.remove("is-changed");
    void element.offsetWidth;
    element.classList.add("is-changed");
  };
  const renderFullscreen = () => {
    if (!fullscreenButton) return;
    fullscreenButton.textContent = fullscreenActive ? "退出全屏" : "进入全屏";
    fullscreenButton.setAttribute("aria-pressed", fullscreenActive ? "true" : "false");
    fullscreenButton.setAttribute("aria-label", fullscreenActive ? "退出浏览器全屏" : "进入浏览器全屏");
  };
  const paint = (runtime, save) => {
    const data = runtime && typeof runtime === "object" ? runtime : {};
    const collections = data.collections && typeof data.collections === "object" ? data.collections : {};
    const items = Array.isArray(collections["durable-items"]) ? collections["durable-items"] : [];
    const lantern = items.find(item => item && item.id === "salt-lantern");
    const ration = items.find(item => item && item.id === "fog-ration");
    const lanternDurability = Number(lantern && lantern.durability);
    const lanternMax = Number(lantern && lantern.maxDurability);
    const rationDurability = Number(ration && ration.durability);
    const rationUses = Number(ration && ration.uses);
    const focus = Number(data.variables && data.variables.focus);
    if (lanternCount) lanternCount.textContent = Number.isFinite(lanternDurability) ? "耐久 " + lanternDurability + " / " + (Number.isFinite(lanternMax) ? lanternMax : "—") + " · 已用 " + (Number.isFinite(Number(lantern && lantern.uses)) ? Number(lantern.uses) : 0) + " 次" : "未找到提灯";
    if (rationCount) rationCount.textContent = Number.isFinite(rationDurability) ? "余量 " + rationDurability + " 份 · 已用 " + (Number.isFinite(rationUses) ? rationUses : 0) + " 次" : "未找到口粮";
    if (lanternButton) lanternButton.disabled = submittingAction || !Number.isFinite(lanternDurability) || lanternDurability < 1;
    if (rationButton) rationButton.disabled = submittingAction || !Number.isFinite(rationDurability) || rationDurability < 1 || !Number.isFinite(focus) || focus >= 8;
    const values = { lantern: lanternDurability, ration: rationDurability, focus, clues: Number(data.variables && data.variables.clues), gate: Boolean(data.variables && data.variables["gate-open"]) };
    if (previousValues) Object.keys(values).forEach(key => { if (String(previousValues[key]) !== String(values[key])) pulse(document.querySelector("[data-keeper-value=" + key + "]")); });
    previousValues = values;
    const clues = Array.isArray(collections["clue-board"]) ? collections["clue-board"] : [];
    if (clueList) {
      clueList.replaceChildren();
      clues.forEach(clue => {
        const item = document.createElement("li");
        const confirmed = clue && clue.status === "confirmed";
        item.dataset.confirmed = confirmed ? "true" : "false";
        item.textContent = (confirmed ? "已确认 · " : "待确认 · ") + String(clue && clue.title ? clue.title : "未命名线索");
        clueList.append(item);
      });
    }
    if (endButton) endButton.disabled = !!(save && save.state && save.state.ending && save.state.ending.status === "ended");
  };
  const refresh = async () => {
    try {
      const context = await TavernExtension.getContext();
      paint(context && context.save && context.save.state && context.save.state.runtime, context && context.save);
      fullscreenActive = !!(context && context.ui && context.ui.fullscreen);
      renderFullscreen();
    } catch (error) { setStatus("读取船坞状态失败：" + error.message, false, true); }
  };
  const submitAction = async (button, actionId, text) => {
    if (submittingAction || !button || button.disabled) return;
    submittingAction = true;
    button.disabled = true;
    try {
      setStatus("正在请求 " + text + "……", true);
      await TavernExtension.choose(text + "。", { actionId });
      setStatus("行动已提交，等待本回合结算。", true);
    } catch (error) { setStatus("行动失败：" + error.message, false, true); }
    finally { submittingAction = false; refresh(); }
  };
  lanternButton?.addEventListener("click", () => submitAction(lanternButton, "use-salt-lantern", "点亮盐火提灯"));
  rationButton?.addEventListener("click", () => submitAction(rationButton, "eat-fog-ration", "食用潮雾口粮"));
  fullscreenButton?.addEventListener("click", async () => {
    if (fullscreenBusy) return;
    fullscreenBusy = true;
    fullscreenButton.disabled = true;
    try {
      const result = fullscreenActive ? await TavernExtension.exitFullscreen() : await TavernExtension.fullscreen();
      fullscreenActive = !!(result && result.fullscreen);
      renderFullscreen();
      setStatus(fullscreenActive ? "已进入浏览器全屏。" : "已退出浏览器全屏；当前为窗口化界面。", false);
    } catch (error) { setStatus("全屏切换失败：" + error.message, false, true); }
    finally { fullscreenBusy = false; fullscreenButton.disabled = false; refresh(); }
  });
  terminalButton?.addEventListener("click", async () => {
    try { await TavernExtension.openTerminal(); setStatus("AI 终端已打开。", false); }
    catch (error) { setStatus("终端打开失败：" + error.message, false, true); }
  });
  endButton?.addEventListener("click", async () => {
    if (endButton.disabled) return;
    try {
      const context = await TavernExtension.getContext();
      const rule = context && context.world && context.world.ending ? context.world.ending : {};
      const endingId = rule.defaultEndingId || "player-choice";
      const ending = Array.isArray(rule.endings) ? rule.endings.find(item => item && item.id === endingId) : null;
      if (!window.confirm("确定以“" + (ending && ending.label ? ending.label : "玩家主动结束") + "”结束当前世界线吗？结束后仍可从世界库重开。")) return;
      endButton.disabled = true;
      setStatus("正在保存世界线结局……", true);
      await TavernExtension.endWorld({ endingId, confirm: true });
      setStatus("本局已结束，进度已保存。", false);
      await refresh();
    } catch (error) { endButton.disabled = false; setStatus("结束世界线失败：" + error.message, false, true); }
  });
  exitButton?.addEventListener("click", async () => {
    try { await TavernExtension.exitWorld(); }
    catch (error) { setStatus("返回世界库失败：" + error.message, false, true); }
  });
  TavernExtension.on("turn.start", () => setStatus("正在请求 AI……", true));
  TavernExtension.on("agent.execute", () => setStatus("正在结算声明动作……", true));
  TavernExtension.on("agent.complete", () => setStatus("正在写入航海日志……", true));
  TavernExtension.on("turn.commit", () => { setStatus("本回合已保存。", false); refresh(); });
  TavernExtension.on("turn.error", event => { setStatus("回合失败：" + (event && event.message ? event.message : "请重试"), false, true); refresh(); });
  window.addEventListener("tavern-context", event => {
    const context = event.detail || {};
    paint(context.save && context.save.state && context.save.state.runtime, context.save);
    fullscreenActive = !!(context.ui && context.ui.fullscreen);
    renderFullscreen();
  });
  renderFullscreen();
  TavernExtension.getContext().then(context => { paint(context && context.save && context.save.state && context.save.state.runtime, context && context.save); fullscreenActive = !!(context && context.ui && context.ui.fullscreen); renderFullscreen(); setStatus("雾港船坞已连接。", false); }).catch(error => setStatus("连接失败：" + error.message, false, true));
})();
